      // 加载当前线索的事件
      async function loadCurrentClueEvents() {
        var clueNum = currentStrategyPage;
        var container = document.getElementById('yyEventsContainer');
        container.innerHTML = '<div class="yy-loading">正在加载...</div>';

        try {
          var result = await STscript('/xbgetvar 攻略.事件.线索' + clueNum, {
            handleExecutionErrors: false,
            handleParserErrors: false,
          });

          // ========== 调试日志开始 ==========
          console.log('=== [攻略进度] 调试信息 ===');
          console.log('当前线索编号:', clueNum);
          console.log('原始返回值 (result):', result);
          console.log('返回值类型:', typeof result);
          console.log('返回值是否为null:', result === null);
          console.log('返回值是否为undefined:', result === undefined);
          if (result && typeof result === 'object') {
            console.log('返回值的keys:', Object.keys(result));
            console.log('是否有pipe字段:', 'pipe' in result);
