    <script>
      function showPage(page) {
        var contents = document.querySelectorAll('.yy-page-content');
        var buttons = document.querySelectorAll('.yy-page-btn');
        var labels = ['一', '二', '三'];

        for (var i = 0; i < contents.length; i++) {
          if (Number(contents[i].dataset.pageContent) === page) {
            contents[i].classList.add('yy-active');
          } else {
            contents[i].classList.remove('yy-active');
          }
        }

        for (var j = 0; j < buttons.length; j++) {
          if (Number(buttons[j].dataset.page) === page) {
            buttons[j].classList.add('yy-active');
            buttons[j].textContent = '● 线索' + labels[j];
          } else {
            buttons[j].classList.remove('yy-active');
            buttons[j].textContent = '○ 线索' + labels[j];
          }
        }

        // 更新攻略进度页
        currentStrategyPage = page;
        updateCurrentStage(); // 更新阶段标签

        // 如果攻略面板是展开的，重新加载事件
        var panel = document.getElementById('yyStrategyPanel');
        if (panel && panel.classList.contains('yy-expanded')) {
          loadCurrentClueEvents();
        }
      }

      // 从SillyTavern变量读取诊疗日记内容
      async function loadDiaryFromVariables() {
        // 检查STscript函数是否可用
        if (typeof STscript !== 'function') {
          console.error('[诊疗日记] STscript函数不可用');
          return;
        }

        console.log('[诊疗日记] 开始加载变量...');

        const fields = [
          { key: '观察记录', selectorIndex: 0 }, // 第1个 .yy-diagnosis-box
          { key: '患者表述', selectorIndex: 0 }, // 第1个 .yy-small-box
          { key: '行为模式', selectorIndex: 1 }, // 第2个 .yy-small-box
          { key: '治疗师备注', isNotes: true }, // .yy-medication-list 里的 span
        ];

        for (let i = 1; i <= 3; i++) {
          const pageEl = document.querySelector(`.yy-page-content[data-page-content="${i}"]`);
          if (!pageEl) continue;

          for (const field of fields) {
            const varKey = `诊疗日记.线索${i}.${field.key}`;

            try {
              const valueRaw = await STscript(`/getvar ${varKey}`);
              let value = valueRaw;

              // 提取pipe字段
              if (typeof valueRaw === 'object' && valueRaw !== null) {
                if (valueRaw.pipe !== undefined) {
                  value = valueRaw.pipe;
                } else {
                  // 如果是对象但没有pipe字段，说明变量不存在
                  value = '';
                }
              }

              const content = String(value || '').trim();

              if (content) {
                let targetEl;

                if (field.key === '观察记录') {
                  targetEl = pageEl.querySelector('.yy-diagnosis-box');
                } else if (field.key === '患者表述') {
                  targetEl = pageEl.querySelectorAll('.yy-small-box')[0];
                } else if (field.key === '行为模式') {
                  targetEl = pageEl.querySelectorAll('.yy-small-box')[1];
                } else if (field.isNotes) {
                  // 治疗师备注：使用innerHTML支持HTML标签
                  targetEl = pageEl.querySelector('.yy-medication-list');
                }

                if (targetEl) {
                  if (field.isNotes) {
                    targetEl.innerHTML = content; // 支持HTML
                    console.log(`[诊疗日记] ✅ 线索${i} ${field.key}: 已更新（HTML）`);
                  } else {
                    targetEl.textContent = content; // 纯文本
                    console.log(`[诊疗日记] ✅ 线索${i} ${field.key}: ${content.length}字`);
                  }
                }
              } else {
                console.warn(`[诊疗日记] ⚠️ 线索${i} ${field.key}: 为空`);
                // 为空时弹出toastr警告
                if (window.toastr) {
                  window.toastr.warning(
                    `线索${i} 的 "${field.key}" 字段为空，可能是AI生成时标签未正确闭合。请检查初始化脚本的AI输出。`,
                    '诊疗日记字段缺失',
                    { timeOut: 8000 },
                  );
                }
              }
            } catch (e) {
              console.error(`[诊疗日记] ❌ 读取${varKey}失败:`, e);
            }
          }
        }

        console.log('[诊疗日记] 变量加载完成');
      }

      // 初始化按钮点击处理
      async function handleInitialize() {
        const button = document.getElementById('yy-initButton');
        const loadingText = document.getElementById('yy-loadingText');

        // 读取用户输入的文本
        const fetishInput = document.getElementById('yyFetishInput').value.trim();

        if (!fetishInput) {
          window.toastr && window.toastr.warning('请输入你的性癖偏好再开始生成');
          return;
        }

        console.log('[初始化] 用户输入:', fetishInput);

        button.disabled = true;
        loadingText.style.display = 'block';

        try {
          // 检查STscript函数是否可用
          if (typeof STscript !== 'function') {
            throw new Error('STscript函数不可用,请确保在小白X模板环境中运行');
          }

          // 第一步：设置用户偏好变量
          console.log('[初始化] 1/2 设置用户偏好变量...');
          await STscript(`/setvar key=用户性癖 ${fetishInput}`);

          // 第二步：调用初始化脚本
          console.log('[初始化] 2/2 调用初始化脚本...');

          // 检查小白X全局对象
          console.log('[初始化] 检查环境 - window.xb:', typeof window.xb);
          console.log('[初始化] 检查环境 - window.xbqte:', typeof window.xbqte);

          let scriptTriggered = false;

          // 方法1：使用小白X的全局函数（如果存在）
          if (typeof window.xbqte === 'function') {
            console.log('[初始化] 使用 window.xbqte() 调用...');
            try {
              await window.xbqte('诊疗日记');
              scriptTriggered = true;
              console.log('[初始化] xbqte() 调用成功');
            } catch (e) {
              console.error('[初始化] xbqte() 调用失败:', e);
            }
          }

          // 方法2：通过executeSlashCommandsWithOptions调用（作为聊天消息）
          if (!scriptTriggered) {
            console.log('[初始化] 尝试通过 executeSlash + 自动发送...');
            try {
              // 添加超时保护
              const executePromise = STscript('/xbqte 诊疗日记', {
                handleExecutionErrors: false,
                abortSignal: null,
              });

              const timeoutPromise = new Promise((_, reject) =>
                setTimeout(() => reject(new Error('executeSlash 超时（5秒）')), 5000),
              );

              console.log('[初始化] 等待 executeSlash 返回...');
              const result = await Promise.race([executePromise, timeoutPromise]);

              console.log('[初始化] executeSlash 返回成功:', result);
              console.log('[初始化] 返回类型:', typeof result);
              console.log('[初始化] 返回内容:', JSON.stringify(result));

              // 检查返回结果
              if (result && typeof result === 'object') {
                if (result.pipe && result.pipe.includes('错误')) {
                  console.error('[初始化] executeSlash 返回错误:', result.pipe);
                  throw new Error(result.pipe);
                } else {
                  console.log('[初始化] executeSlash 执行成功，pipe:', result.pipe);
                  scriptTriggered = true;
                }
              } else {
                console.log('[初始化] executeSlash 返回了非对象结果，假定成功');
                scriptTriggered = true;
              }
            } catch (e) {
              console.log('[初始化] executeSlash 未立即返回（这是正常的，/xbqte 是异步命令）');
              // 不要阻止后续方法尝试
            }
          }

          // 方法3：尝试通过聊天输入框模拟用户输入
          if (!scriptTriggered) {
            console.log('[初始化] 尝试通过聊天框模拟输入...');
            const textarea = document.getElementById('send_textarea');
            const sendButton = document.getElementById('send_but');

            console.log('[初始化] textarea 元素:', textarea ? '找到' : '未找到');
            console.log('[初始化] sendButton 元素:', sendButton ? '找到' : '未找到');

            if (textarea && sendButton) {
              console.log('[初始化] 开始模拟聊天框输入...');
              const originalValue = textarea.value;
              textarea.value = '/xbqte 诊疗日记';

              // 触发 input 事件
              textarea.dispatchEvent(new Event('input', { bubbles: true }));
              console.log('[初始化] 已设置 textarea 内容并触发 input 事件');

              // 等待一帧
              await new Promise(resolve => setTimeout(resolve, 50));

              // 点击发送按钮
              console.log('[初始化] 准备点击发送按钮...');
              sendButton.click();
              console.log('[初始化] ✅ 命令已通过聊天框发送');
              scriptTriggered = true;

              // 恢复原值
              setTimeout(() => {
                textarea.value = originalValue;
                textarea.dispatchEvent(new Event('input', { bubbles: true }));
                console.log('[初始化] 已恢复 textarea 原始值');
              }, 200);
            } else {
              console.log('[初始化] 未找到聊天框元素（在iframe中正常），跳过方法3');
            }
          }

          // 方法4：假定脚本已触发（因为 /xbqte 是异步的，可能不会立即返回）
          if (!scriptTriggered) {
            console.log('[初始化] executeSlash 可能已异步触发，直接进入等待阶段...');
            scriptTriggered = true; // 假定已触发，进入轮询检测
          }

          // 等待脚本执行完成（轮询检测）
          console.log('[初始化] 等待AI生成...');
          loadingText.textContent = '正在生成攻略配置，请耐心等待...';

          let attempts = 0;
          const maxAttempts = 120; // 最多等待120秒
          let found = false;

          while (!found && attempts < maxAttempts) {
            await new Promise(resolve => setTimeout(resolve, 1000));
            attempts++;

            // 每3秒检查一次变量
            if (attempts % 3 === 0) {
              try {
                const checkResult = await STscript('/getvar 诊疗日记.线索1.观察记录', { abortSignal: null });

                let value = checkResult;

                // 提取 pipe 字段
