                  if (checkResult.pipe !== undefined) {
                    value = checkResult.pipe;
                  }
                }

                const valueStr = String(value || '');
                const trimmedLength = valueStr.trim().length;

                // 检查是否为有效字符串（非空）
                if (typeof value === 'string' && trimmedLength > 0) {
                  console.log('[初始化] ✅ 检测到变量已写入！内容预览:', value.substring(0, 50) + '...');
                  found = true;
                  break;
                }
                // 不再输出"变量仍为空"的日志，减少噪音
              } catch (e) {
                // 静默处理检查失败
              }
            }

            // 每10秒输出一次日志
            if (attempts % 10 === 0) {
              console.log(`[初始化] 等待中... ${attempts}秒`);
            }
          }

          if (!found) {
            throw new Error(`初始化超时（${attempts}秒），请检查小白X脚本是否正确运行`);
          }

          // 初始化完成，隐藏封面，显示主内容，加载变量
